import React from 'react';import Seo from '../components/Seo';
export function Legal(){return <><Seo title="Mentions légales" path="/mentions-legales" description="Mentions légales du site Beyond31."/><section className="legal-page"><p className="mono">MENTIONS LÉGALES</p><h1>Informations du site</h1><h2>Éditeur</h2><p>Beyond31 est édité par <strong>Huriel Nguimbi</strong>, basé à Poitiers, France.</p><p>Contact : <a href="mailto:contact@beyond31.online">contact@beyond31.online</a></p><h2>Responsable de publication</h2><p>Huriel Nguimbi.</p><h2>Hébergement</h2><p>Les informations d’hébergement doivent être renseignées selon l’hébergeur effectivement utilisé lors de la mise en production.</p><h2>Propriété intellectuelle</h2><p>Sauf mention contraire, les contenus, créations graphiques et éléments originaux présentés sur Beyond31 sont protégés. Les marques, logos et contenus appartenant à des tiers restent la propriété de leurs titulaires respectifs.</p></section></>}
export function Privacy(){return <><Seo title="Confidentialité" path="/confidentialite" description="Politique de confidentialité du site Beyond31."/><section className="legal-page"><p className="mono">CONFIDENTIALITÉ</p><h1>Le minimum de données.</h1><p>Beyond31 est conçu comme un portfolio. Le site n’intègre pas de formulaire de contact et ne demande pas de compte utilisateur.</p><h2>Contact</h2><p>Lorsque vous utilisez un lien email, téléphone ou réseau social, l’échange est géré par le service concerné et selon ses propres conditions.</p><h2>Mesure d’audience</h2><p>Aucun outil d’analyse nécessitant un consentement n’est prévu dans cette version. Si un outil est ajouté ultérieurement, cette page devra être mise à jour.</p><h2>Sécurité</h2><p>Le site applique des en-têtes de sécurité côté hébergement et limite les scripts et ressources externes autorisés.</p></section></>}
